/**
 * 🚀 Lanzar Bloque / Estructura en Mano (120 FPS Sólidos + Rotación Exacta)
 *
 * - Dispara el bloque o estructura seleccionado en la hotbar con tiro parabólico.
 * - Respeta fielmente la orientación elegida (caja@1, caja@8, etc.).
 * - Detección de colisión completa contra Agentes, Estructuras (mc.structures) y Terreno (mc.grid).
 * - Colocación local idéntica al pico nativo (mcSetBlock + mcRemeshAround local, 0 tirones de FPS).
 * - Agnóstico: ejecuta automáticamente 'alRomper' si el bloque/estructura colocada tiene comportamiento (ej. TNT).
 */
(async function () {
  'use strict';

  const P_VOX = 16;
  const proyectiles = [];
  let animRaf = 0;
  let lastTime = 0;

  if (game.voxelesUI && game.voxelesUI.material) {
    game.voxelesUI.material('proyectil_bloque', { emite: true, luz: 3 });
  }

  const _colores = new Map();
  function colorDeBloque(id, sk) {
    if (sk) return [0.85, 0.65, 0.45];
    if (!id || id <= 0) return [0.75, 0.72, 0.68];
    if (_colores.has(id)) return _colores.get(id);

    let col = [0.75, 0.72, 0.68];
    try {
      const ctx = mc.atlas && mc.atlas.getContext && mc.atlas.getContext('2d');
      if (ctx) {
        const T = typeof MC_TILE !== 'undefined' ? MC_TILE : 16;
        const d = ctx.getImageData(0, (id - 1) * T, 6 * T, T).data;
        let r = 0, g = 0, b = 0, c = 0;
        for (let i = 0; i < d.length; i += 16) {
          if (d[i + 3] > 32) { r += d[i]; g += d[i + 1]; b += d[i + 2]; c++; }
        }
        if (c > 0) col = [r / (c * 255), g / (c * 255), b / (c * 255)];
      }
    } catch (e) {}
    _colores.set(id, col);
    return col;
  }

  function lanzarBloqueEnMano(opc = {}) {
    if (typeof mc === 'undefined' || !mc.pos || !mc.active) return;

    const s = mc.sel || 0;
    const sk = mc.slotStruct && mc.slotStruct[s];
    const id = (mc.hotbar && mc.hotbar[s]) || (sk ? 0 : 1);
    const baseKey = sk || (id && mc.blockKey && mc.blockKey[id]) || 'piedra';

    // Detectar orientación elegida (R / Shift+R / sufijo @ori)
    const liveRot = (typeof mcPreviewOri === 'function') ? mcPreviewOri() : 0;
    const keyOri = (typeof mcClaveOri === 'function') ? mcClaveOri(baseKey) : 0;
    const rot = keyOri || liveRot;

    const fullKey = (rot && typeof mcClaveConOri === 'function')
      ? mcClaveConOri(baseKey, rot)
      : (rot ? (String(baseKey).replace(/@\d+$/, '') + '@' + rot) : baseKey);

    const esc = mc.scale || 1;
    const oy = mc.pos[1] + ((typeof MC_EYE === 'number' ? MC_EYE : 1.62) * esc);
    const cp = Math.cos(mc.pitch || 0);
    const dirX = -Math.sin(mc.yaw || 0) * cp, dirY = Math.sin(mc.pitch || 0), dirZ = -Math.cos(mc.yaw || 0) * cp;
    const rx = Math.cos(mc.yaw || 0), rz = -Math.sin(mc.yaw || 0);

    const vel = opc.velocidad || 32, grav = opc.gravedad || 13.5;
    const x0 = mc.pos[0] + dirX * 0.45 + rx * 0.28 * esc;
    const y0 = oy + dirY * 0.45 - 0.15 * esc;
    const z0 = mc.pos[2] + dirZ * 0.45 + rz * 0.28 * esc;

    const tDist = 28;
    const tx = mc.pos[0] + dirX * tDist, ty = oy + dirY * tDist, tz = mc.pos[2] + dirZ * tDist;
    const d = Math.hypot(tx - x0, ty - y0, tz - z0) || 1;

    proyectiles.push({
      id: Math.random().toString(36).slice(2),
      x: x0, y: y0, z: z0,
      vx: ((tx - x0) / d) * vel, vy: ((ty - y0) / d) * vel, vz: ((tz - z0) / d) * vel,
      grav,
      matId: id,
      matKey: fullKey,
      structKey: sk ? ((typeof mcClaveBase === 'function') ? mcClaveBase(sk) : sk.replace(/@\d+$/, '')) : null,
      claveAColocar: fullKey,
      rot: rot,
      color: colorDeBloque(id, sk)
    });

    while (proyectiles.length > 30) proyectiles.shift();

    if (!animRaf) {
      lastTime = performance.now();
      animRaf = requestAnimationFrame(bucle);
    }
  }

  function bucle(ahora) {
    const dt = Math.min(0.04, (ahora - lastTime) / 1000);
    lastTime = ahora;

    if (game.voxelesUI) game.voxelesUI.limpia('proyectil_bloque');

    let dirty = null;

    for (let i = proyectiles.length - 1; i >= 0; i--) {
      const p = proyectiles[i];
      p.vy -= p.grav * dt;
      const nx = p.x + p.vx * dt, ny = p.y + p.vy * dt, nz = p.z + p.vz * dt;

      const paso = Math.hypot(nx - p.x, ny - p.y, nz - p.z);
      const sub = Math.max(1, Math.ceil(paso / 0.35));
      let choco = false, hX = nx, hY = ny, hZ = nz, norm = [0, 1, 0];

      for (let s = 1; s <= sub; s++) {
        const t = s / sub;
        const x = p.x + (nx - p.x) * t, y = p.y + (ny - p.y) * t, z = p.z + (nz - p.z) * t;

        // 1. Esqueletos / Agentes
        if (game.esqueletos && game.esqueletos.enPunto) {
          const esq = game.esqueletos.enPunto(x, y, z);
          if (esq) {
            if (game.sangre) game.sangre.salpica(esq.punto || [x, y, z]);
            if (game.esqueletos.empujar) game.esqueletos.empujar(esq.id || esq.rig, 14, p.vx / (paso || 1), p.vz / (paso || 1));
            choco = true; break;
          }
        }

        const bx = Math.floor(x), by = Math.floor(y), bz = Math.floor(z);

        // 2. Estructuras estampadas (mc.structures)
        let hitStruct = false;
        if (typeof mc !== 'undefined' && mc && mc.structures && mc.structures.length > 0) {
          const T = (typeof MC_TILE !== 'undefined' ? MC_TILE : 16);
          const fx = Math.floor(x * T), fy = Math.floor(y * T), fz = Math.floor(z * T);
          if (typeof mcAimSolidAt === 'function' && mcAimSolidAt(fx, fy, fz)) {
            hitStruct = true;
          } else if (typeof mcStructCellSolid === 'function' && mcStructCellSolid(bx, by, bz)) {
            hitStruct = true;
          }
        }

        if (hitStruct) {
          choco = true; hX = x; hY = y; hZ = z;
          const pt = Math.max(0, t - 1 / sub);
          const prevBx = Math.floor(p.x + (nx - p.x) * pt);
          const prevBy = Math.floor(p.y + (ny - p.y) * pt);
          const prevBz = Math.floor(p.z + (nz - p.z) * pt);
          let nX = prevBx - bx, nY = prevBy - by, nZ = prevBz - bz;
          if (nX === 0 && nY === 0 && nZ === 0) {
            const ax = Math.abs(p.vx), ay = Math.abs(p.vy), az = Math.abs(p.vz);
            if (ay >= ax && ay >= az) nY = p.vy > 0 ? -1 : 1;
            else if (ax >= az) nX = p.vx > 0 ? -1 : 1;
            else nZ = p.vz > 0 ? -1 : 1;
          } else {
            // Asegurar que la normal sea unitaria
            if (Math.abs(nY) >= Math.abs(nX) && Math.abs(nY) >= Math.abs(nZ)) { nX = 0; nY = Math.sign(nY); nZ = 0; }
            else if (Math.abs(nX) >= Math.abs(nZ)) { nX = Math.sign(nX); nY = 0; nZ = 0; }
            else { nX = 0; nY = 0; nZ = Math.sign(nZ); }
          }
          norm = [nX, nY, nZ];
          break;
        }

        // 3. Terreno (mc.grid)
        if (mcInside && mcInside(bx, by, bz)) {
          const gridId = mc.grid[mcIdx(bx, by, bz)] || 0;
          if (gridId !== 0 && !(typeof mcIsCellReplaceable === 'function' && mcIsCellReplaceable(bx, by, bz))) {
            choco = true; hX = x; hY = y; hZ = z;
            const pt = Math.max(0, t - 1 / sub);
            const prevBx = Math.floor(p.x + (nx - p.x) * pt);
            const prevBy = Math.floor(p.y + (ny - p.y) * pt);
            const prevBz = Math.floor(p.z + (nz - p.z) * pt);
            let nX = prevBx - bx, nY = prevBy - by, nZ = prevBz - bz;
            if (nX === 0 && nY === 0 && nZ === 0) {
              const ax = Math.abs(p.vx), ay = Math.abs(p.vy), az = Math.abs(p.vz);
              if (ay >= ax && ay >= az) nY = p.vy > 0 ? -1 : 1;
              else if (ax >= az) nX = p.vx > 0 ? -1 : 1;
              else nZ = p.vz > 0 ? -1 : 1;
            } else {
              if (Math.abs(nY) >= Math.abs(nX) && Math.abs(nY) >= Math.abs(nZ)) { nX = 0; nY = Math.sign(nY); nZ = 0; }
              else if (Math.abs(nX) >= Math.abs(nZ)) { nX = Math.sign(nX); nY = 0; nZ = 0; }
              else { nX = 0; nY = 0; nZ = Math.sign(nZ); }
            }
            norm = [nX, nY, nZ];
            break;
          }
        }
      }

      if (choco) {
        const tx = Math.floor(hX) + (norm[0] || 0);
        const ty = Math.floor(hY) + (norm[1] || 0);
        const tz = Math.floor(hZ) + (norm[2] || 0);

        if (mcInside && mcInside(tx, ty, tz)) {
          const clave = p.claveAColocar || p.matKey || p.structKey || p.matId;
          const esMulti = p.structKey && (typeof mcCabeEnRejilla === 'function') && !mcCabeEnRejilla(p.structKey);

          if (esMulti && typeof mcStampStruct === 'function') {
            mcStampStruct(p.structKey, tx, ty, tz, p.rot || 0);
          } else {
            // Colocación nativa local ultrarrápida (0 FPS drop, sin mcFlushBuild)
            const bId = (typeof mcResolveMat === 'function') ? mcResolveMat(clave) : (clave | 0);
            if (bId && typeof mcSetBlock === 'function') {
              mcSetBlock(tx, ty, tz, bId);
              dirty = dirty
                ? { x0: Math.min(dirty.x0, tx), z0: Math.min(dirty.z0, tz), x1: Math.max(dirty.x1, tx), z1: Math.max(dirty.z1, tz) }
                : { x0: tx, z0: tz, x1: tx, z1: tz };
            }
          }

          // Agnóstico: ejecutar alRomper si el bloque colocado tiene cualquier comportamiento al romperse
          if (game.bloques && typeof game.bloques.avisoDeRotura === 'function') {
            setTimeout(() => {
              const avisa = game.bloques.avisoDeRotura(tx, ty, tz);
              if (avisa) {
                if (typeof mcSetBlock === 'function') {
                  mcSetBlock(tx, ty, tz, 0);
                  if (typeof mcRemeshAround === 'function') mcRemeshAround(tx, tz);
                }
                avisa();
              }
            }, 40);
          }
        }
        proyectiles.splice(i, 1);
        continue;
      }

      p.x = nx; p.y = ny; p.z = nz;

      // Renderizar cubo 2x2x2
      if (game.voxelesUI) {
        const fx = Math.floor(p.x * P_VOX), fy = Math.floor(p.y * P_VOX), fz = Math.floor(p.z * P_VOX);
        for (let dx = 0; dx <= 1; dx++) {
          for (let dy = 0; dy <= 1; dy++) {
            for (let dz = 0; dz <= 1; dz++) {
              game.voxelesUI.pon(fx + dx, fy + dy, fz + dz, p.color, 'proyectil_bloque');
            }
          }
        }
      }
    }

    // Re-mallar estrictamente de forma local por chunk como el pico nativo (0 tirones de FPS)
    if (dirty && typeof mcRemeshAround === 'function') {
      mcRemeshAround(dirty.x0, dirty.z0, dirty.x1, dirty.z1);
      if (typeof mcScheduleSave === 'function') mcScheduleSave();
    }

    if (proyectiles.length > 0) {
      animRaf = requestAnimationFrame(bucle);
    } else {
      animRaf = 0;
      if (game.voxelesUI) game.voxelesUI.limpia('proyectil_bloque');
    }
  }

  game.onKey('g', () => { lanzarBloqueEnMano(); });
  game.lanzarBloque = lanzarBloqueEnMano;
  window.lanzarBloque = lanzarBloqueEnMano;
})();
